const msg=$input.first().json.message||{};
const text=(msg.text||'').trim();
const chatId=(msg.chat&&msg.chat.id)||'';
const nowIst=new Date(Date.now()+330*60000).toISOString().replace('T',' ').slice(0,16);
const sys='You are the command parser for a video automation bot. Convert the user message into strict JSON. Times the user gives are in IST (Asia/Kolkata). Respond JSON only.';
const usr=`Current IST time: ${nowIst}.
User message: "${text}"
Return JSON: {
 "action": "generate | settime | setplatform | status | help",
 "topic": "video topic if given else empty",
 "datetime_ist": "YYYY-MM-DD HH:MM if a specific post time is given, else empty",
 "best_time": true/false (true if user wants best/optimal time or no specific time),
 "platform": "youtube | tiktok | both | empty",
 "daily_time": "HH:MM if user wants to set a daily posting time, else empty"
}`;
return [{ json:{ chatId, rawText:text, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.1, max_tokens:300 } } }];

const prev=$('🧠 Build Intent Prompt').first().json;
const raw=$input.first().json.choices[0].message.content;
let o={};try{o=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)o=JSON.parse(m[0]);}
// convert IST datetime to UTC ISO
function istToUtc(s){ if(!s) return ''; const d=new Date(s.replace(' ','T')+':00+05:30'); return isNaN(d)?'':d.toISOString(); }
return [{ json:{ chatId:prev.chatId, rawText:prev.rawText, action:o.action||'help', topic:o.topic||'', platform:(o.platform||'').trim(), best_time: o.best_time!==false, daily_time:o.daily_time||'', postAtUtc: istToUtc(o.datetime_ist), datetime_ist:o.datetime_ist||'' } }];

const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
let lines=rows.map(r=>`• [${r.status}] ${r.title||'(untitled)'}${r.scheduled_time?(' → '+new Date(new Date(r.scheduled_time).getTime()+330*60000).toISOString().slice(0,16).replace('T',' ')+' IST'):''}`);
const txt= rows.length? ('📊 *Last 10 in queue:*\n'+lines.join('\n')) : 'Queue is empty. Send me a topic to generate a video!';
return [{ json:{ chatId:$('📋 Parse Intent').first().json.chatId, statusText:txt } }];

const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
const s={};rows.forEach(r=>s[r.key]=r.value);
const dailyEnabled=(s.daily_enabled||'true')==='true';
const dailyTime=(s.daily_time||'18:00');
// current IST HH:MM
const ist=new Date(Date.now()+330*60000);
const hh=String(ist.getUTCHours()).padStart(2,'0');
const mm=String(ist.getUTCMinutes()).padStart(2,'0');
const curHour=hh;
const tgtHour=(dailyTime.split(':')[0]||'18').padStart(2,'0');
// fire when the hour matches (runs hourly, so match on hour)
const isTime = dailyEnabled && curHour===tgtHour;
return [{ json:{ isTime, dailyTime, platform:(s.platform||'youtube'), nowIst:`${hh}:${mm}` } }];

const s=$('🕐 Is It Posting Time?').first().json;
// daily auto-run: no fixed topic (data-driven), publish at best time, platform from settings
return [{ json:{ topic:'', platform:s.platform||'youtube', postAtUtc:'', best_time:true, source:'schedule', chatId: $vars.TELEGRAM_CHAT_ID || '' } }];

const req=$input.first().json;
const topRaw=$('📈 Research: Top Performers').first().json;
const top=(Array.isArray(topRaw)?topRaw:(topRaw.data||[])).map(r=>`\"${r.title}\" (score ${r.performance})`);
const plat=req.platform|| 'youtube';
const sys=`You are a world-class short-form content strategist. You understand hooks, retention curves, and viral patterns for ${plat}. Respond with strict JSON only.`;
let usr;
if(req.topic){ usr=`The creator requested this exact topic: \"${req.topic}\".\nSharpen it into the highest-retention angle.\nReturn JSON: {\"topic\":\"refined specific topic\",\"content_pillar\":\"education|inspiration|story|listicle|howto\",\"target_audience\":\"who\",\"hook_angle\":\"the curiosity/tension angle\"}`; }
else { const data= top.length?`Past winners to emulate:\n- ${top.join('\n- ')}`:'No history yet; pick a proven evergreen angle.'; usr=`${data}\nChoose a fresh, trend-aware topic for ${plat}.\nReturn JSON: {\"topic\":\"specific topic\",\"content_pillar\":\"education|inspiration|story|listicle|howto\",\"target_audience\":\"who\",\"hook_angle\":\"the curiosity/tension angle\"}`; }
return [{ json:{ ...req, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.8, max_tokens:400 } } }];

const prev=$('🧭 Agent: Strategy').first().json;
const raw=$input.first().json.choices[0].message.content;
let s={};try{s=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)s=JSON.parse(m[0]);}
const sys='You are an award-winning short-form scriptwriter. Use this proven structure: PATTERN-INTERRUPT HOOK (0-3s) -> escalating value BEATS -> surprising PAYOFF -> crisp CTA. Write natural spoken narration (no stage directions). Each beat = one scene with narration, a punchy on-screen caption (<=6 words), and a SPECIFIC stock-footage search keyword (visual nouns). Respond with strict JSON only.';
const usr=`Topic: ${s.topic}\nAudience: ${s.target_audience}\nHook angle: ${s.hook_angle}\nPillar: ${s.content_pillar}\nConstraints: total spoken 90-140 words; 5 scenes; conversational, punchy, no filler.\nReturn JSON: {\"hook\":\"spoken hook line\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"...\",\"broll_keyword\":\"...\"}],\"cta\":\"spoken CTA\"}`;
return [{ json:{ ...prev, topic:s.topic, content_pillar:s.content_pillar, target_audience:s.target_audience, hook_angle:s.hook_angle, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1200 } } }];

const prev=$('✍️ Agent: Script').first().json;
const raw=$input.first().json.choices[0].message.content;
let sc={};try{sc=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)sc=JSON.parse(m[0]);}
const scenes=(sc.scenes||[]).slice(0,6).map((x,i)=>({ idx:i, narration:x.narration||'', on_screen_text:x.on_screen_text||'', broll_keyword:x.broll_keyword||prev.topic }));
const fullScript=[sc.hook,...scenes.map(s=>s.narration),sc.cta].filter(Boolean).join(' ');
const sys='You are a YouTube/TikTok packaging + SEO expert. Generate scroll-stopping metadata. Respond with strict JSON only.';
const usr=`Topic: ${prev.topic}\nAudience: ${prev.target_audience}\nReturn JSON: {\"title\":\"<=70 char curiosity title, no false claims\",\"description\":\"2-3 sentences, keywords + CTA\",\"tags\":\"12 comma-separated keywords\",\"hashtags\":\"8 space-separated #tags\"}`;
return [{ json:{ ...prev, hook:sc.hook||'', scenes, cta:sc.cta||'', script:fullScript, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.7, max_tokens:500 } } }];

const prev=$('🔍 Agent: SEO').first().json;
const raw=$input.first().json.choices[0].message.content;
let o={};try{o=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)o=JSON.parse(m[0]);}
const thumbPrompt=`Ultra eye-catching vertical 9:16 thumbnail for a short video titled \"${o.title||prev.topic}\". Bold dramatic lighting, one striking focal subject, vivid saturated colors, strong emotion, cinematic depth, leaves clear negative space at the top for text overlay. No text, no watermark.`;
return [{ json:{ ...prev, title:(o.title||prev.topic||'').slice(0,95), description:o.description||'', tags:o.tags||'', hashtags:o.hashtags||'', imageBody:{ model:'gpt-image-1', prompt:thumbPrompt, size:'1024x1536', quality:'high', n:1 } } }];

const prev=$('🎨 Agent: Thumbnail').first().json;
const resp=$input.first().json;
let hosted='';try{hosted=resp.data.url||resp.data.display_url;}catch(e){}
return [{ json:{ platform:prev.platform, source:prev.source, chatId:prev.chatId, postAtUtc:prev.postAtUtc, best_time:prev.best_time, topic:prev.topic, content_pillar:prev.content_pillar, target_audience:prev.target_audience, hook:prev.hook, cta:prev.cta, script:prev.script, scenes:prev.scenes, title:prev.title, description:prev.description, tags:prev.tags, hashtags:prev.hashtags, thumbnail_url:hosted } }];

// RUN ONCE FOR ALL ITEMS — build a single ffmpeg bash script
const master=$('🧩 Assemble Record').first().json;
const scenes=$('🎬 Split Scenes').all().map(i=>i.json);
const pex=$input.all().map(i=>i.json);
const KEY=$vars.OPENAI_API_KEY;
const FONT=$vars.FFMPEG_FONT || '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf';
const voice=$vars.OPENAI_TTS_VOICE || 'onyx';
const job='v3_'+Date.now();
const dir='/tmp/'+job;
const b64=(s)=>Buffer.from(String(s||''),'utf8').toString('base64');
function pickVideo(r){ try{const v=r.videos||[];if(!v.length)return '';const f=v[0].video_files||[];const port=f.filter(x=>x.height>=x.width);const pool=port.length?port:f;pool.sort((a,b)=>(b.height||0)-(a.height||0));return (pool[0]||{}).link||'';}catch(e){return '';} }
const L=['set -e','export DIR='+dir,'mkdir -p $DIR','cd $DIR'];
const list=[];
scenes.forEach((s,i)=>{
  const broll=pickVideo(pex[i]||{});
  const tts=JSON.stringify({ model:'tts-1-hd', voice:voice, input: s.narration||master.topic });
  L.push(`echo \"${b64(tts)}\" | base64 -d > tts_${i}.json`);
  L.push(`curl -s https://api.openai.com/v1/audio/speech -H \"Authorization: Bearer ${KEY}\" -H \"Content-Type: application/json\" --data @tts_${i}.json -o voice_${i}.mp3`);
  L.push(`echo \"${b64(s.on_screen_text)}\" | base64 -d > cap_${i}.txt`);
  if(broll){ L.push(`curl -sL \"${broll}\" -o src_${i}.mp4`); }
  else { L.push(`curl -sL \"${master.thumbnail_url}\" -o src_${i}.jpg`); }
  L.push(`D=$(ffprobe -v error -show_entries format=duration -of csv=p=0 voice_${i}.mp3)`);
  const inp = broll ? `-stream_loop -1 -t $D -i src_${i}.mp4` : `-loop 1 -t $D -i src_${i}.jpg`;
  const vf = `scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,drawtext=fontfile=${FONT}:textfile=cap_${i}.txt:fontcolor=white:fontsize=64:line_spacing=12:box=1:boxcolor=black@0.55:boxborderw=26:x=(w-text_w)/2:y=h-560`;
  L.push(`ffmpeg -y ${inp} -i voice_${i}.mp3 -vf \"${vf}\" -map 0:v -map 1:a -r 30 -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -b:a 192k -shortest scene_${i}.mp4`);
  list.push(`file 'scene_${i}.mp4'`);
});
L.push(`printf \"${list.join('\\n')}\\n\" > list.txt`);
L.push(`ffmpeg -y -f concat -safe 0 -i list.txt -c copy ${dir}/final.mp4`);
L.push(`echo RENDER_DONE ${dir}/final.mp4`);
return [{ json:{ ...master, job, outPath:dir+'/final.mp4', ffmpegScript:L.join('\n') } }];

const m=$('🎞️ Build FFmpeg Job').first().json;
const publicUrl=`${$vars.SUPABASE_URL}/storage/v1/object/public/videos/${m.job}.mp4`;
// compute scheduled_time
function bestSlotUtc(platform){
  const slotsRaw = platform==='tiktok' ? ($vars.BEST_TIMES_TIKTOK||'12:00,19:00,21:00') : ($vars.BEST_TIMES_YOUTUBE||'15:00,18:00,20:00');
  const slots=slotsRaw.split(',').map(s=>s.trim());
  const nowUtc=new Date();
  for(const slot of slots){
    const [h,mn]=slot.split(':').map(Number);
    // slot is IST; convert to today's UTC: IST = UTC+5:30 => UTC = IST-5:30
    const d=new Date(nowUtc);
    d.setUTCHours(h-5, mn-30, 0, 0);
    // normalize negative
    const t=new Date(d.getTime());
    if(t>nowUtc) return t.toISOString();
  }
  // none left today -> first slot tomorrow
  const [h,mn]=slots[0].split(':').map(Number);
  const d=new Date(nowUtc); d.setUTCDate(d.getUTCDate()+1); d.setUTCHours(h-5, mn-30,0,0);
  return d.toISOString();
}
let sched = m.postAtUtc && !m.best_time ? m.postAtUtc : bestSlotUtc(m.platform||'youtube');
if(!sched) sched=bestSlotUtc(m.platform||'youtube');
const istStr=new Date(new Date(sched).getTime()+330*60000).toISOString().slice(0,16).replace('T',' ');
return [{ json:{ platform:m.platform||'youtube', source:m.source, chat_id:String(m.chatId||''), topic:m.topic, title:m.title, description:m.description, tags:m.tags, hashtags:m.hashtags, script:m.script, scenes:m.scenes, thumbnail_url:m.thumbnail_url, video_path:m.outPath, video_url:publicUrl, status:'ready', scheduled_time:sched, scheduledIst:istStr } }];

